package org.brightstats.data;

import java.util.*;
import java.security.MessageDigest;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;

/** Explicit category order and source-row policy; no fitted numeric distance between levels. */
public final class OrdinalData {
    private OrdinalData(){}
    public record Specification(List<String> columns,List<List<String>> orderedLevels,boolean completeCases){public Specification{columns=List.copyOf(columns);orderedLevels=orderedLevels.stream().map(List::copyOf).toList();if(columns.size()<2||columns.size()>16||columns.size()!=orderedLevels.size()||new HashSet<>(columns).size()!=columns.size()||columns.stream().anyMatch(String::isBlank))throw new IllegalArgumentException("Select 2–16 distinct ordinal source columns and their ordered levels.");for(var levels:orderedLevels)if(levels.size()<2||levels.size()>12||new HashSet<>(levels).size()!=levels.size()||levels.stream().anyMatch(String::isBlank))throw new IllegalArgumentException("Declare 2–12 unique nonempty ordered labels per variable.");}}
    public record Provenance(int suppliedRows,List<Integer> sourceRows,int excludedRows,Specification specification,String selectedDataSha256){public Provenance{sourceRows=List.copyOf(sourceRows);}}
    public record Prepared(int[][] codes,Provenance provenance){public Prepared{codes=Arrays.stream(codes).map(int[]::clone).toArray(int[][]::new);}@Override public int[][] codes(){return Arrays.stream(codes).map(int[]::clone).toArray(int[][]::new);}}
    public static String category(String value,DataPreparation.Kind kind,DataPreparation.Settings settings){if(kind!=DataPreparation.Kind.NUMERIC)return value.strip();double number=DataPreparation.number(value,settings.decimal());return Double.toString(number==0?0:number);}
    public static List<String> observedLevels(DataPreparation.Raw raw,DataPreparation.Settings settings,List<DataPreparation.Column> definitions,int column){var kind=definitions.get(column).kind();Set<String> levels=new HashSet<>();for(var row:raw.rows()){String value=row.get(column);if(!DataPreparation.missing(value,settings))levels.add(category(value,kind,settings));if(levels.size()>12)throw new IllegalArgumentException(definitions.get(column).name()+" has more than 12 observed values; declare a suitable ordered variable or explicitly recode first.");}return levels.stream().sorted(kind==DataPreparation.Kind.NUMERIC?Comparator.comparingDouble(Double::parseDouble):Comparator.naturalOrder()).map(value->kind==DataPreparation.Kind.NUMERIC&&settings.decimal()==DataPreparation.Decimal.COMMA?value.replace('.',','):value).toList();}
    public static Prepared prepare(DataPreparation.Raw raw,DataPreparation.Settings settings,List<DataPreparation.Column> definitions,Specification specification){
        if(raw.rows().size()>10000||definitions.size()!=raw.headers().size())throw new IllegalArgumentException("Ordinal workflows support at most 10,000 supplied source rows with consistent column definitions.");int p=specification.columns().size();int[] columns=new int[p];List<Map<String,Integer>> maps=new ArrayList<>();
        for(int j=0;j<p;j++){columns[j]=-1;for(int k=0;k<definitions.size();k++)if(definitions.get(k).name().equals(specification.columns().get(j))){if(columns[j]>=0)throw new IllegalArgumentException("Ambiguous ordinal source column identity.");columns[j]=k;}if(columns[j]<0)throw new IllegalArgumentException("An ordinal source column is unavailable: "+specification.columns().get(j));Map<String,Integer> order=new HashMap<>();for(int k=0;k<specification.orderedLevels().get(j).size();k++){String key=category(specification.orderedLevels().get(j).get(k),definitions.get(columns[j]).kind(),settings);if(order.put(key,k)!=null)throw new IllegalArgumentException("Equivalent numeric labels were declared as different ordinal categories.");}maps.add(order);}
        List<int[]> codes=new ArrayList<>();List<Integer> rows=new ArrayList<>();for(int i=0;i<raw.rows().size();i++){org.brightstats.stats.Matrices.interrupted();int[] row=new int[p];boolean missing=false;for(int j=0;j<p;j++){String value=raw.rows().get(i).get(columns[j]);if(DataPreparation.missing(value,settings)){missing=true;continue;}Integer code=maps.get(j).get(category(value,definitions.get(columns[j]).kind(),settings));if(code==null)throw new IllegalArgumentException("Undeclared nonmissing category in "+specification.columns().get(j)+", source row "+(i+1)+". Declare its order or explicitly mark it missing.");row[j]=code;}if(missing){if(!specification.completeCases())throw new IllegalArgumentException("Selected ordinal source indicators contain missing cells. Explicitly choose complete selected rows or revise preparation; no mean-imputed categories are used.");continue;}codes.add(row);rows.add(i+1);}
        if(codes.size()<50)throw new IllegalArgumentException("At least 50 complete selected source rows are required for this ordinal workflow.");int[][] values=codes.toArray(int[][]::new);return new Prepared(values,new Provenance(raw.rows().size(),rows,raw.rows().size()-rows.size(),specification,hash(values,rows,specification)));
    }
    private static String hash(int[][] values,List<Integer> rows,Specification spec){try{var digest=MessageDigest.getInstance("SHA-256");digest.update("bright-stats-ordinal-v1".getBytes(StandardCharsets.UTF_8));put(digest,spec.columns().size());for(String name:spec.columns())put(digest,name);for(var levels:spec.orderedLevels()){put(digest,levels.size());for(String level:levels)put(digest,level);}put(digest,values.length);for(int i=0;i<values.length;i++){put(digest,rows.get(i));for(int code:values[i])put(digest,code);}return HexFormat.of().formatHex(digest.digest());}catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}}
    private static void put(MessageDigest digest,int value){digest.update(ByteBuffer.allocate(4).putInt(value).array());}
    private static void put(MessageDigest digest,String value){byte[] bytes=value.getBytes(StandardCharsets.UTF_8);put(digest,bytes.length);digest.update(bytes);}
}
